record.field:
if record.production_id:
 prod_order = env['mrp.production'].search([('id', '=', record.production_id.id)],limit=1)
 if prod_order:
   record['original_mo'] = prod_order.original_mo

if record.production_id and record.operation_id:
  update = env['mrp_bom_general_cost'].search([('prod_bom_general_cost_ids', '=', record.production_id.id), ('operation_id', '=', record.operation_id.id)], limit=1)
  if update:
    update.write({'operation_id':record.operation_id.id,'actual_qty':record.duration/60.00,'planned_qty':record.duration_expected/60.00})

if record.production_id and record.operation_id:
  ot_applicable = False
  #######################
  work_center = env['mrp.workcenter'].search([('id', '=', record.workcenter_id.id)])
  if work_center:
    for work_centers in work_center:
      if work_centers.ot_cost_per_hour > 0.00:
        #work_centers.write({'costs_hour':(work_centers.overhead_cost_hour + work_centers.general_cost_hour + work_centers.ot_cost_per_hour)}) 
        work_centers.write({'costs_hour':(work_centers.ot_cost_per_hour)})
      else:
        #work_centers.write({'costs_hour':(work_centers.labour_cost_hour + work_centers.overhead_cost_hour + work_centers.general_cost_hour)})
        work_centers.write({'costs_hour':(work_centers.labour_cost_hour)}) 

  #######################
  update = env['mrp_bom_labour_cost'].search([('prod_bom_labour_cost_ids', '=', record.production_id.id), ('operation_id', '=', record.operation_id.id)], limit=1)
  if update:
    if record.ot_applicable == False:
      if record.workcenter_id.ot_cost_per_hour > 0.00:
        ot_applicable = True
    else:
      ot_applicable = True

    #actual_cost = update.operation_id.workcenter_id.labour_cost_hour + update.operation_id.workcenter_id.labour_idle_cost_per_hour + update.operation_id.workcenter_id.ot_cost_per_hour
    #actual_cost = update.operation_id.workcenter_id.labour_cost_hour + update.operation_id.workcenter_id.ot_cost_per_hour
    actual_cost = update.operation_id.workcenter_id.costs_hour 
    actual_cost_ot = update.operation_id.workcenter_id.ot_cost_per_hour
    #actual_cost_without_ot = update.operation_id.workcenter_id.labour_cost_hour + update.operation_id.workcenter_id.labour_idle_cost_per_hour
    actual_cost_without_ot = update.operation_id.workcenter_id.labour_cost_hour
    update.write({'operation_id':record.operation_id.id,'actual_qty':record.duration/60.00,'planned_qty':record.duration_expected/60.00,'cost':actual_cost,'cost_ot':actual_cost_ot,'cost_without_ot':actual_cost_without_ot})

    record['ot_applicable'] = ot_applicable

if record.production_id and record.operation_id:
  update = env['mrp_bom_overhead_cos'].search([('prod_bom_overhead_cost_ids', '=', record.production_id.id), ('operation_id', '=', record.operation_id.id)], limit=1)
  if update:
    update.write({'operation_id':record.operation_id.id,'actual_qty':record.duration/60.00,'planned_qty':record.duration_expected/60.00})
